window.kbPageData["cards/d3be0409f1d3d9208d7bdb82"] = {"qs":{"国考 2025 地市级 行测#13":{"paper":"国考 2025 地市级 行测","n":13,"mod":"政治理论","src":["31f401e91aef8d11365d.pdf",3],"asrc":["8cece062c7c079b53130.pdf",5],"m":[],"task":"从宣传思想文化工作的多项部署中辨认其首要政治任务。","current_affairs":{"state":"是","event":"全国宣传思想文化工作会议传达习近平总书记关于宣传思想文化工作的重要指示","year":2023,"basis":"作答需要掌握该指示明确的首要政治任务。"},"links":[{"id":"k-5463af2ea6914a4a","label":"宣传思想文化工作的首要政治任务","catalog_id":null,"type":"制度与规则","role":"直接考查","field":"question","quote":"用党的创新理论武装全党、教育人民","why":"解析确认重要指示明确将用党的创新理论武装全党、教育人民列为首要政治任务。","origin":"逐题标记","originalId":"k-b4ba07f3316e4b25"}],"stem":"习近平总书记指出，宣传思想文化工作事关党的前途命运，事关国家长治久安，事关民族凝聚力和向心力，是一\n项极端重要的工作。宣传思想文化工作的首要政治任务是：","options":["培育和践行社会主义核心价值观","用党的创新理论武装全党、教育人民","提升国家文化软实力和中华文化影响力","赓续中华文脉、推动中华优秀传统文化创造性转化和创新性发展"],"answer":"B","analysis":"13. 正确答案：B\n解析：\n本题考查理论与政策。\n2023年10月7日至8日，全国宣传思想文化工作会议在北京召开。会上传达了习近平总书记对宣传思想文化工作作出\n的重要指示。\nB项正确，A、C、D三项错误，习近平总书记强调，宣传思想文化工作面临新形势新任务，必须要有新气象新作为。\n要坚持以新时代中国特色社会主义思想为指导，全面贯彻党的二十大精神，聚焦用党的创新理论武装全党、教育人\n民这个首要政治任务······着力培育和践行社会主义核心价值观······着力赓续中华文脉、推动中华优秀传统文化创造\n性转化和创新性发展······不断提升国家文化软实力和中华文化影响力，为全面建设社会主义现代化国家、全面推进\n中华民族伟大复兴提供坚强思想保证、强大精神力量、有利文化条件。\n故正确答案为B。\n【考点】\n社会建设,重大会议及讲话","figs":[],"state":"已标记","notes":[],"domains":["政治理论","文化"],"nature":"知识题","current":true},"国考 2025 地市级 行测#14":{"paper":"国考 2025 地市级 行测","n":14,"mod":"政治理论","src":["31f401e91aef8d11365d.pdf",3],"asrc":["8cece062c7c079b53130.pdf",5],"m":[],"task":"区分完善大统战工作格局与加强人民当家作主制度建设的具体措施。","current_affairs":{"state":"是","event":"党的二十届三中全会通过进一步全面深化改革的《决定》，部署完善大统战工作格局","year":2024,"basis":"作答需要区分《决定》在全过程人民民主制度体系下分别部署的改革措施。"},"links":[{"id":"k-440f6bbced89d97b","label":"完善大统战工作格局的制度举措","catalog_id":null,"type":"制度与规则","role":"直接考查","field":"answer","quote":"完善发挥统一战线凝聚人心、汇聚力量政治作用的政策举措。","why":"党外代表人士队伍建设、铸牢中华民族共同体意识和亲清政商关系建设均列入《决定》的统战改革部署。","origin":"逐题标记"},{"id":"k-95dcffde921a07f8","label":"人民当家作主制度建设中的人大议事和听证制度","catalog_id":null,"type":"制度与规则","role":"直接考查","field":"answer","quote":"（29）加强人民当家作主制度建设······健全人\n大议事规则和论证、评估、评议、听证制度。","why":"《决定》将人大议事规则和相关程序列入加强人民当家作主制度建设的部署。","origin":"逐题标记"}],"stem":"完善大统战工作格局，是习近平总书记关于做好新时代党的统一战线工作的重要思想的重要内容，是做好新时代\n统战工作的重要保障，也是进一步全面深化改革、为推进中国式现代化凝心聚力的重要举措。下列各项不属于完善\n大统战格局措施的是：","options":["更好发挥党外人士作用，健全党外代表人士队伍建设制度","制定民族团结进步促进法，健全铸牢中华民族共同体意识制度机制","全面构建亲清政商关系，健全促进非公有制经济健康发展、非公有制经济人士健康成长工作机制","健全人大议事规则和论证、评估、评议、听证制度"],"answer":"D","analysis":"14. 正确答案：D\n解析：\n本题考查理论与政策。\n2024年7月18日，中国共产党第二十届中央委员会第三次全体会议正式通过《中共中央关于进一步全面深化改革 推\n进中国式现代化的决定》（以下简称《决定》）。\nA、B、C三项正确，《决定》在“八、健全全过程人民民主制度体系”部分指出：“（32）完善大统战工作格局。完善\n发挥统一战线凝聚人心、汇聚力量政治作用的政策举措。坚持好、发展好、完善好中国新型政党制度。更好发挥党\n外人士作用，健全党外代表人士队伍建设制度。制定民族团结进步促进法，健全铸牢中华民族共同体意识制度机\n制，增强中华民族凝聚力。系统推进我国宗教中国化，加强宗教事务治理法治化。完善党外知识分子和新的社会阶\n层人士政治引领机制。全面构建亲清政商关系，健全促进非公有制经济健康发展、非公有制经济人士健康成长工作\n机制。完善港澳台和侨务工作机制。”\nD项错误，《决定》在“八、健全全过程人民民主制度体系”部分指出：“（29）加强人民当家作主制度建设······健全人\n大议事规则和论证、评估、评议、听证制度。丰富人大代表联系人民群众的内容和形式。健全吸纳民意、汇集民智\n工作机制。发挥工会、共青团、妇联等群团组织联系服务群众的桥梁纽带作用。”\n本题为选非题，故正确答案为D。\n【考点】\n政治建设,重要文件","figs":[],"state":"已标记","notes":[],"domains":["政治理论"],"nature":"知识题","current":true},"国考 2025 地市级 行测#15":{"paper":"国考 2025 地市级 行测","n":15,"mod":"政治理论","src":["31f401e91aef8d11365d.pdf",3],"asrc":["8cece062c7c079b53130.pdf",5],"m":[],"task":"核对健全绿色低碳发展机制的举措，辨明两种双控制度的转型方向。","current_affairs":{"state":"是","event":"党的二十届三中全会通过进一步全面深化改革的《决定》，部署健全绿色低碳发展机制","year":2024,"basis":"题目要求掌握该次全会明确的双控制度转型方向。"},"links":[{"id":"k-8c1fa4140851f799","label":"能耗双控向碳排放双控全面转型","catalog_id":null,"type":"制度与规则","role":"直接考查","field":"answer","quote":"建立能耗双控向\n碳排放双控全面转型新机制。","why":"《决定》将能耗双控确定为转型起点，将碳排放双控确定为转型方向。","origin":"逐题标记"}],"stem":"党的二十届三中全会提出，健全绿色低碳发展机制，实施支持绿色低碳发展的财税、金融、投资、价格政策和标\n准体系，发展绿色低碳产业，健全绿色消费激励机制，促进绿色低碳循环发展经济体系建设。关于健全绿色低碳发\n展机制，下列举措不恰当的是：","options":["优化政府绿色采购政策，完善绿色税制","建立碳排放双控向能耗双控全面转型新机制","完善资源总量管理和全面节约制度，健全废弃物循环利用体系","加快规划建设新型能源体系，完善新能源消纳和调控政策措施"],"answer":"B","analysis":"15. 正确答案：B\n解析：\n本题考查理论与政策。\nA、C、D三项正确，B项错误，《中共中央关于进一步全面深化改革、推进中国式现代化的决定》“十二、深化生态\n文明体制改革”部分指出：“（49）健全绿色低碳发展机制。实施支持绿色低碳发展的财税、金融、投资、价格政策和\n标准体系，发展绿色低碳产业，健全绿色消费激励机制，促进绿色低碳循环发展经济体系建设。优化政府绿色采购\n政策，完善绿色税制。完善资源总量管理和全面节约制度，健全废弃物循环利用体系。健全煤炭清洁高效利用机\n制。加快规划建设新型能源体系，完善新能源消纳和调控政策措施。完善适应气候变化工作体系。建立能耗双控向\n碳排放双控全面转型新机制。构建碳排放统计核算体系、产品碳标识认证制度、产品碳足迹管理体系，健全碳市场\n交易制度、温室气体自愿减排交易制度，积极稳妥推进碳达峰碳中和。”\n本题为选非题，故正确答案为B。\n【考点】\n经济建设,重要文件","figs":[],"state":"已标记","notes":[],"domains":["政治理论","生态环境"],"nature":"知识题","current":true}},"materialFiles":{},"terms":{"k-5463af2ea6914a4a":{"id":"k-5463af2ea6914a4a","mode":"k","type":"制度与规则","title":"宣传思想文化工作的首要政治任务","qs":[],"count":3},"k-440f6bbced89d97b":{"id":"k-440f6bbced89d97b","mode":"k","type":"制度与规则","title":"大统战工作格局","qs":[],"count":2},"k-95dcffde921a07f8":{"id":"k-95dcffde921a07f8","mode":"k","type":"制度与规则","title":"人大议事规则和论证、评估、评议、听证制度","qs":[],"count":3},"k-8c1fa4140851f799":{"id":"k-8c1fa4140851f799","mode":"k","type":"制度与规则","title":"能耗双控向碳排放双控全面转型","qs":[],"count":1}},"questions":{}};
